class _FirstTagTextParser(HTMLParser):
    def __init__(self, target_tag: str):
        super().__init__()
        self.target = target_tag.lower()
        self.found = False
        self.depth = 0
        self.chunks = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if not self.found:
            if tag == self.target:
                self.found = True
                self.depth = 1
        else:
            # inside target, nested start increases depth
            self.depth += 1

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        # self-closing tag encountered
        if not self.found and tag == self.target:
            # found a self-closing target tag (no text)
            self.found = True
            self.depth = 0  # immediate close

    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.found:
            # reduce depth for nested tags; if depth reaches 0, we've closed the target
            if self.depth > 0:
                self.depth -= 1
            # When depth becomes 0 after closing the outermost tag, stop further processing by setting a marker.
            # (We still allow parser to finish safely; caller will check found & content.)

    def handle_data(self, data):
        if self.found and (self.depth > 0 or self.depth == 0):
            # If the target is self-closing, depth may be 0; no text will be appended.
            # For a normal found tag, depth >= 1 while inside; append text pieces.
            # Use conservative check: if found and we haven't completed parsing outer tag, collect.
            if self.depth >= 1:
                self.chunks.append(data)

