            except Exception:
                char = '?'
            self.chunks.append(char)

    def handle_charref(self, name):
        if self.found and self.depth >= 1:
            try:
                if name.startswith('x') or name.startswith('X'):
                    val = int(name[1:], 16)
                else:
                    val = int(name, 10)
                self.chunks.append(chr(val))
            except Exception:
                self.chunks.append('?')

def get_first_tag_text(url: str, tag: str, timeout: int = 10, headers: Optional[dict] = None) -> Optional[str]:
    """
    Fetches the page at `url`, finds the first occurrence of the HTML tag named `tag`,
    and returns its textual content (inner text). Returns None if the tag is not found
    or on network errors.

    Parameters:
    - url: full URL to fetch (http:// or https://)
    - tag: tag name to search for (e.g., 'h1', 'p', 'title'), case-insensitive
    - timeout: network timeout in seconds
    - headers: optional dict of HTTP headers (e.g., {'User-Agent': 'MyBot/1.0'})

    Example:
      text = get_first_tag_text('https://example.com', 'h1')
