from typing import Any, Dict, List, Optional, Tuple
import math

def _get_nested(item: Dict[str, Any], key: str) -> Any:
    """Retrieve nested value using dot-separated key, e.g. 'meta.price'."""
    parts = key.split(".")
    cur = item
    for p in parts:
        if not isinstance(cur, dict) or p not in cur:
            return None
        cur = cur[p]
    return cur

def analyze_stock_column(
    records: List[Dict[str, Any]],
    column: str,
    *,
    strict: bool = False
) -> Dict[str, Optional[float]]:
    """
    Analyze a list of stock data records and compute sum, mean, min, and max
    for the specified column.

    Parameters:
    - records: list of dict-like records (e.g. [{"close": 10.5}, {"close": "11.2"}, ...])
    - column: column name to analyze. Supports nested keys with dot notation, e.g. "meta.price"
    - strict: if True, raise ValueError when a non-numeric or missing value is encountered.
              if False (default), non-numeric or missing values are skipped.

    Returns a dict: {"sum": float|None, "mean": float|None, "min": float|None, "max": float|None}
    If no numeric values are found, all four entries will be None.
    """
    numbers: List[float] = []

    for i, rec in enumerate(records):
        if not isinstance(rec, dict):
            if strict:
                raise ValueError(f"Record at index {i} is not a dict: {rec!r}")
            else:
                continue

        raw = _get_nested(rec, column)

        if raw is None:
            if strict:
                raise ValueError(f"Missing column '{column}' in record at index {i}: {rec!r}")
            else:
