        if isinstance(raw, (int, float)):
            val = float(raw)
        else:
            try:
                # strip common thousand separators and whitespace
                s = str(raw).strip().replace(",", "")
                val = float(s)
            except Exception:
                if strict:
                    raise ValueError(f"Non-numeric value for column '{column}' at index {i}: {raw!r}")
                else:
                    continue

        if math.isfinite(val):
            numbers.append(val)
        else:
            if strict:
                raise ValueError(f"Non-finite numeric value for column '{column}' at index {i}: {raw!r}")
            # else skip NaN or inf

    if not numbers:
        return {"sum": None, "mean": None, "min": None, "max": None}

    total = math.fsum(numbers)
    mn = min(numbers)
    mx = max(numbers)
    mean = total / len(numbers)

    return {"sum": total, "mean": mean, "min": mn, "max": mx}

