    """
    Extract numerical values from a nested JSON-like structure following `path`
    and visualize them.

    Args:
      json_obj: The JSON-like object (nested dicts/lists / scalars).
      path: Either:
          - dot-separated string of keys, e.g. "a.b.*.value"
          - list of tokens, where each token is a str key, '*' for wildcard,
            or an int index to index lists, e.g. ["a", "b", "*", "value"] or ["rows", 0, "value"]
      plot_type: "line" (default) or "hist" for histogram.
      bins: number of bins if plot_type == "hist".
      title/xlabel/ylabel: optional labels for the plot.
      show: whether to call plt.show().
      save_path: optional path to save figure (png, pdf, ...). If provided, the figure is saved.

    Returns:
      (values, fig) where values is a list of floats extracted, fig is the matplotlib Figure.

    Raises:
      ValueError: if no numeric values are found or plot_type unsupported.
    """

    # Normalize path into list of tokens
    if isinstance(path, str):
        tokens: List[Union[str, int]] = [t for t in path.split(".") if t != ""]
    else:
        tokens = list(path)

    def traverse(nodes: List[Any], token: Union[str, int]) -> List[Any]:
        next_nodes: List[Any] = []
        if token == "*":
            # wildcard: iterate dict values or list items
            for n in nodes:
                if isinstance(n, dict):
                    next_nodes.extend(n.values())
                elif isinstance(n, (list, tuple)):
                    next_nodes.extend(n)
                # else: nothing to add
        elif isinstance(token, int):
            # index into lists
            idx = token
            for n in nodes:
                if isinstance(n, (list, tuple)):
                    if -len(n) <= idx < len(n):
                        next_nodes.append(n[idx])
        else:
            # token is treated as a key (string)
            key = token
            for n in nodes:
                if isinstance(n, dict):
                    if key in n:
                        next_nodes.append(n[key])
                # also allow indexing lists by string keys that are numeric indices
                elif isinstance(n, (list, tuple)):
                    # try to interpret key as integer index
                    try:
                        idx = int(key)
                    except Exception:
                        continue
                    if -len(n) <= idx < len(n):
                        next_nodes.append(n[idx])
        return next_nodes

    # initial nodes
    current_nodes = [json_obj]
    for tok in tokens:
        current_nodes = traverse(current_nodes, tok)
        if not current_nodes:
            break  # early exit if nothing to follow

    # Helper to flatten and find numeric values
    def is_numeric_scalar(x: Any) -> bool:
        return isinstance(x, numbers.Number)

    def try_parse_number(x: Any) -> Optional[float]:
        if is_numeric_scalar(x):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except Exception:
                return None
        return None

    def collect_numbers(n: Any, out: List[float]) -> None:
        # recursively collect numeric entries from n
        if n is None:
            return
        num = try_parse_number(n)
        if num is not None:
            out.append(num)
            return
        if isinstance(n, dict):
            for v in n.values():
                collect_numbers(v, out)
        elif isinstance(n, (list, tuple, set)):
            for item in n:
                collect_numbers(item, out)
        # else: not numeric, ignore

    extracted: List[float] = []
    for node in current_nodes:
        collect_numbers(node, extracted)

    if not extracted:
        raise ValueError("No numeric values extracted using the provided path.")

    # Create plot
    fig, ax = plt.subplots()
    if plot_type.lower() in ("line", "plot"):
        ax.plot(extracted, marker="o", linestyle="-")
        ax.set_title(title or "Line plot of extracted values")
        ax.set_xlabel(xlabel or "Index")
        ax.set_ylabel(ylabel or "Value")
    elif plot_type.lower() in ("hist", "histogram"):
        ax.hist(extracted, bins=bins)
        ax.set_title(title or "Histogram of extracted values")
        ax.set_xlabel(xlabel or "Value")
        ax.set_ylabel(ylabel or "Count")
    else:
        plt.close(fig)
        raise ValueError(f"Unsupported plot_type '{plot_type}'. Use 'line' or 'hist'.")

    fig.tight_layout()
    if save_path:
        fig.savefig(save_path)
    if show:
        plt.show()

    return extracted, fig


