               If time_str is aware, this is ignored (but still validated if provided).
    - to_tz: IANA timezone name to convert to.
    - fmt_in: optional strptime format to parse time_str. If None, uses dateutil.parser.parse.
    - fmt_out: optional strftime format for output. If None, returns ISO 8601 string.
    - disambiguate: how to handle DST problems for naive local times:
        - "raise" (default): raise on ambiguous or nonexistent local times.
        - "earliest": for ambiguous times, choose the earlier (usually DST) occurrence.
        - "latest": for ambiguous times, choose the later (usually standard) occurrence.
        - "shift_forward": for nonexistent times (clock jump forward), shift forward minute-by-minute
                           until a valid local time is found (up to search_limit_minutes).
        - "shift_backward": similar but shift backward.
        - "closest": for nonexistent times, search both directions and pick the nearest valid time.
    - search_limit_minutes: limit for minute-by-minute search when shifting for nonexistent times.

    Returns:
    - Converted time as string (formatted with fmt_out if provided, else ISO 8601).

    Raises:
    - ValueError for parsing problems or invalid timezone names or when disambiguation fails.
    """
    # Parse input datetime
    if fmt_in:
        try:
            dt = datetime.strptime(time_str, fmt_in)
        except Exception as e:
            raise ValueError(f"Couldn't parse time_str with fmt_in: {e}")
    else:
        try:
            dt = parser.parse(time_str)
        except Exception as e:
            raise ValueError(f"Couldn't parse time_str: {e}")

    # If parsed datetime is timezone-aware, just convert
    if dt.tzinfo is not None:
        try:
            tz_to = pytz.timezone(to_tz)
        except Exception as e:
            raise ValueError(f"Invalid to_tz '{to_tz}': {e}")
        converted = dt.astimezone(tz_to)
        return converted.strftime(fmt_out) if fmt_out else converted.isoformat()

    # For naive datetimes, from_tz must be provided
    if not from_tz:
        raise ValueError("from_tz must be provided for naive input datetimes")

    try:
        tz_from = pytz.timezone(from_tz)
    except Exception as e:
        raise ValueError(f"Invalid from_tz '{from_tz}': {e}")

    # Helper to attempt localization with various strategies
    def try_localize(naive_dt):
        try:
            return tz_from.localize(naive_dt, is_dst=None)
        except AmbiguousTimeError:
            if disambiguate in ("earliest", "dst_true", "first"):
                return tz_from.localize(naive_dt, is_dst=True)
            elif disambiguate in ("latest", "dst_false", "second"):
                return tz_from.localize(naive_dt, is_dst=False)
            elif disambiguate == "raise":
                raise
            else:
                raise ValueError(f"Ambiguous time and unsupported disambiguate value: {disambiguate}")
        except NonExistentTimeError:
            if disambiguate == "raise":
                raise
            # For nonexistent times, try minute-by-minute shifting
            if disambiguate in ("shift_forward", "shift_backward", "closest"):
                orig = naive_dt
                max_steps = max(1, int(search_limit_minutes))
                # For closest, we will search both directions and pick nearest successful
                if disambiguate == "closest":
                    forward_dt = None
                    backward_dt = None
                    # Search forward
                    for i in range(1, max_steps + 1):
                        candidate = orig + timedelta(minutes=i)
                        try:
                            forward_dt = tz_from.localize(candidate, is_dst=None)
                            forward_steps = i
                            break
                        except NonExistentTimeError:
                            continue
                        except AmbiguousTimeError:
                            # choose earliest for ambiguous when searching
                            forward_dt = tz_from.localize(candidate, is_dst=True)
                            forward_steps = i
                            break
                    # Search backward
                    for i in range(1, max_steps + 1):
                        candidate = orig - timedelta(minutes=i)
                        try:
                            backward_dt = tz_from.localize(candidate, is_dst=None)
                            backward_steps = i
                            break
                        except NonExistentTimeError:
                            continue
                        except AmbiguousTimeError:
                            backward_dt = tz_from.localize(candidate, is_dst=True)
                            backward_steps = i
                            break
                    # Pick nearest
                    candidates = []
                    if forward_dt is not None:
                        candidates.append((forward_steps, forward_dt))
                    if backward_dt is not None:
                        candidates.append((backward_steps, backward_dt))
                    if not candidates:
                        raise ValueError("Could not resolve nonexistent time within search_limit_minutes")
                    chosen = min(candidates, key=lambda x: x[0])[1]
                    return chosen
                else:
                    step = 1 if disambiguate == "shift_forward" else -1
                    for i in range(1, max_steps + 1):
                        candidate = naive_dt + timedelta(minutes=step * i)
                        try:
                            return tz_from.localize(candidate, is_dst=None)
                        except NonExistentTimeError:
                            continue
                        except AmbiguousTimeError:
                            # pick earliest for ambiguous found during search
                            return tz_from.localize(candidate, is_dst=True)
                    raise ValueError("Could not resolve nonexistent time within search_limit_minutes")
            else:
                raise ValueError(f"Nonexistent local time and unsupported disambiguate value: {disambiguate}")

    # Attempt localization
    try:
        aware_from_dt = try_localize(dt)
    except AmbiguousTimeError:
        raise ValueError("Ambiguous local time (repeated during DST end); set disambiguate to 'earliest' or 'latest'")
    except NonExistentTimeError:
        raise ValueError("Nonexistent local time (skipped during DST start); set disambiguate to 'shift_forward'/'shift_backward'/'closest'")

    # Convert to target timezone
    try:
        tz_to = pytz.timezone(to_tz)
    except Exception as e:
        raise ValueError(f"Invalid to_tz '{to_tz}': {e}")

    converted = aware_from_dt.astimezone(tz_to)
    return converted.strftime(fmt_out) if fmt_out else converted.isoformat()
