```python
import re
import socket
import urllib.parse
from collections import defaultdict
from typing import Dict, Any, List
import requests

def extract_urls_and_geolocate(text: str, ip_api_base: str = "http://ip-api.com/json/",
                                timeout: float = 5.0) -> Dict[str, Any]:
    """
    Extract all URLs from the provided text, determine the domain for each,
    resolve domain to IP addresses, and query the IP API (ip-api.com) for geolocation data.
    Returns a dict keyed by domain with structure:
      {
        domain: {
          "urls": [list of original matched url strings or domain strings],
          "ips": [list of resolved IP strings],
          "geo": { ip: geo_response_dict_or_error }
        },
        ...
      }

    Note: This function uses the public ip-api.com service (no API key). Respect its usage limits.
    Requires 'requests' library to be installed.
    """
    # 1) Extract URLs with explicit scheme
    scheme_url_pattern = re.compile(r'https?://[^\s,)\]\}"]+', flags=re.I)
    scheme_urls = scheme_url_pattern.findall(text)

    # 2) Extract bare domains (e.g., example.com) that might not have scheme
    # Domain regex matches typical hostnames with TLD (simplified)
    domain_pattern = re.compile(
        r'\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}\b',
        flags=re.I
    )
    bare_domains = set(domain_pattern.findall(text))

    # Map original matched strings to domains
    domain_to_urls = defaultdict(list)

    def normalize_netloc(netloc: str) -> str:
        """Strip credentials and port from netloc and lowercase"""
        # remove credentials user:pass@
        if "@" in netloc:
            netloc = netloc.split("@", 1)[1]
        # remove port
        if ":" in netloc:
            netloc = netloc.split(":", 1)[0]
        return netloc.lower()

    # Process scheme URLs first
    for u in scheme_urls:
        try:
            p = urllib.parse.urlparse(u)
            domain = normalize_netloc(p.netloc)
            if domain:
                domain_to_urls[domain].append(u)
                # if present in bare_domains, remove to avoid duplicate processing
                if domain in bare_domains:
                    bare_domains.discard(domain)
        except Exception:
            # fallback: try to extract domain via regex match of domain inside string
            m = domain_pattern.search(u)
            if m:
                d = m.group(0).lower()
                domain_to_urls[d].append(u)

    # Process remaining bare domains
    for d in bare_domains:
        # We add the literal domain string as the matched "URL"
        domain_to_urls[d.lower()].append(d)

    # For each domain, resolve IPs and query IP API
    results: Dict[str, Any] = {}
    for domain, urls in domain_to_urls.items():
        entry: Dict[str, Any] = {"urls": urls, "ips": [], "geo": {}}
        ips_set = set()

        # Resolve addresses (IPv4 and IPv6 if desired). We'll collect IPv4/IPv6 from getaddrinfo.
        try:
            infos = socket.getaddrinfo(domain, None)
            for info in infos:
                addr = info[4][0]
                ips_set.add(addr)
        except socket.gaierror as e:
            # resolution failed
            entry["resolution_error"] = str(e)

        entry["ips"] = sorted(ips_set)

        # Query ip-api for each IP. ip-api accepts IPs or hostnames.
        for ip in entry["ips"]:
            try:
                url = urllib.parse.urljoin(ip_api_base, urllib.parse.quote(ip))
                params = {
                    "fields": "status,message,query,country,regionName,city,lat,lon,isp,org,as"
                }
                resp = requests.get(url, params=params, timeout=timeout)
                # If API returns non-200, provide error info
                if resp.status_code != 200:
                    entry["geo"][ip] = {"error": f"HTTP {resp.status_code}", "raw_text": resp.text}
                else:
                    data = resp.json()
                    # ip-api returns {"status":"fail", "message":"..."} on errors
                    entry["geo"][ip] = data
            except requests.RequestException as e:
                entry["geo"][ip] = {"error": "request_exception", "message": str(e)}
            except ValueError:
                entry["geo"][ip] = {"error": "invalid_json", "raw_text": resp.text if 'resp' in locals() else None}

        results[domain] = entry

    return results
